          this.gpuDevices = response.devices || [];
          if (this.isGpuBackend && this.gpuDevices.length > 0) {
            this.processDeviceInfo(this.gpuDevices, response.currentDevice ?? 0);
          }
          this.updateBatchSizeRecommendationsWithGpu();
