  // ─── Entity type filtering ─────────────────────────────────────────
  onFilterChanged() {
    this.applyFilters();
    this.cdr.markForCheck();
  }
  toggleAllFilters(on) {
    for (const key of this.allEntityTypes) {
      this.entityTypeFilters[key] = on;
    }
    this.applyFilters();
    this.cdr.markForCheck();
  }
  applyFilters() {
    if (!this.graphData) {
      this.filteredGraphData = null;
      return;
    }
    const enabledTypes = new Set(Object.entries(this.entityTypeFilters).filter(([, v]) => v).map(([k]) => k));
    const nodes = this.graphData.nodes.filter((n) => !n.symbolType || enabledTypes.has(n.symbolType));
    const nodeIds = new Set(nodes.map((n) => n.id));
    const links = this.graphData.links.filter((l) => {
      const src = typeof l.source === "string" ? l.source : l.source.id;
      const tgt = typeof l.target === "string" ? l.target : l.target.id;
      return nodeIds.has(src) && nodeIds.has(tgt);
    });
    this.filteredGraphData = { nodes, links };
  }
