  getAgentIcon(agent) {
    switch (agent) {
      case "claude-code":
        return "smart_toy";
      case "codex":
        return "psychology";
      case "opencode":
        return "code";
      case "qwen":
        return "auto_awesome";
      case "cline":
        return "terminal";
      case "cursor":
        return "mouse";
      case "continue":
        return "play_arrow";
      case "aider":
        return "build";
      case "gemini":
        return "diamond";
      case "kompile":
        return "memory";
      case "pi":
        return "circle";
      default:
        return "smart_toy";
    }
  }
  getDiffTypeIcon(diffType) {
    switch (diffType) {
      case "edit":
        return "edit";
      case "write":
        return "note_add";
      case "patch":
        return "difference";
      default:
        return "code";
    }
  }
  getDiffTypeColor(diffType) {
    switch (diffType) {
      case "edit":
        return "#ff9800";
      case "write":
        return "#4caf50";
      case "patch":
        return "#2196f3";
      default:
        return "#9e9e9e";
    }
  }
  getFileName(filePath) {
    if (!filePath)
      return "";
    const parts = filePath.split("/");
    return parts[parts.length - 1];
  }
  getDirectory(filePath) {
    if (!filePath)
      return "";
    const parts = filePath.split("/");
    return parts.slice(0, -1).join("/");
  }
  getProjectName(projectDir) {
    if (!projectDir)
      return "Unknown";
    const parts = projectDir.split("/");
    return parts[parts.length - 1];
  }
