    "RETRY",
    "RETRY_WITH_BACKOFF",
    "INVOKE_LLM",
    "INVOKE_LLM_FOR_FIX",
    "TRANSITION_STATE",
    "EXECUTE_TASK",
    "NOTIFY",
    "LOG",
    "SKIP",
    "ABORT",
    "AWAIT_APPROVAL",
    "ESCALATE",
    "PARSE_LOG",
    "WAIT_FOR_PROCESS",
    "SEND_TO_AGENT",
    "CUSTOM"
