      description: [""],
      taskType: ["SHELL", Validators.required],
      command: [""],
      workingDirectory: [""],
      timeoutSeconds: [300, [Validators.min(1), Validators.max(86400)]],
      // LLM/Agent Configuration
      promptTemplate: [""],
      autoInvokeLlmOnError: [false],
      llmErrorPromptTemplate: [""],
      agentName: [""],
      systemPrompt: [""],
      // RAG Configuration
      enableRag: [false],
      ragFolderId: [""],
